import WebSocket from 'ws';
import { v4 as uuidv4 } from 'uuid';
import { spawn, execFile } from 'child_process';
import { fileURLToPath } from 'url';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { VERSION } from './version.js';
const BASE_PORT = Number(process.env.FIGMA_HUB_PORT) || 40001;
const PORT_RANGE = 10;
const PORT_FILE = path.join(os.homedir(), '.figma-mcp-hub-port');
const PID_FILE = path.join(os.homedir(), '.figma-mcp-hub-pid');
const COMMAND_TIMEOUT = 30000; // 30 seconds
const BATCH_COMMAND_TIMEOUT = 120000; // 2 minutes for batch operations
const HUB_CONNECT_TIMEOUT = 5000; // 5 seconds to wait for hub startup
const MAX_PENDING = 100;
function readPortFile() {
    try {
        const port = parseInt(fs.readFileSync(PORT_FILE, 'utf-8').trim(), 10);
        return isNaN(port) ? null : port;
    }
    catch {
        return null;
    }
}
function killExistingHub() {
    try {
        const pid = parseInt(fs.readFileSync(PID_FILE, 'utf-8').trim(), 10);
        if (isNaN(pid))
            return;
        process.kill(pid, 'SIGTERM');
        console.error(`[WebSocket] Killed stale hub (PID ${pid})`);
        // Clean up stale files
        try {
            fs.unlinkSync(PID_FILE);
        }
        catch { }
        try {
            fs.unlinkSync(PORT_FILE);
        }
        catch { }
    }
    catch {
        // PID file doesn't exist or process already dead — fine
    }
}
class FigmaWebSocketClient {
    ws = null;
    pendingRequests = new Map();
    isInitialized = false;
    mcpClientInfo = null;
    pluginEditorType = null;
    pluginConnected = false;
    sessionId = uuidv4();
    reconnectTimer = null;
    reconnectAttempts = 0;
    static MAX_RECONNECT_BEFORE_LAUNCH = 3;
    async initialize() {
        if (this.isInitialized)
            return;
        this.isInitialized = true;
        // Try connecting to an existing hub first
        const connected = await this.tryConnect();
        if (connected)
            return;
        // No hub running — launch one
        await this.launchHub();
        // Now connect to it
        const retryConnected = await this.tryConnect();
        if (!retryConnected) {
            console.error('[WebSocket] Failed to connect to hub after launching it');
        }
    }
    readAuthToken() {
        try {
            const tokenPath = path.join(os.homedir(), '.figma-mcp-hub-token');
            return fs.readFileSync(tokenPath, 'utf-8').trim();
        }
        catch {
            return null;
        }
    }
    async launchHub() {
        const lockPath = path.join(os.homedir(), '.figma-mcp-hub.lock');
        // Check if another process is already launching the hub
        try {
            const lockContent = fs.readFileSync(lockPath, 'utf-8').trim();
            const lockTime = parseInt(lockContent, 10);
            // If lock is less than 10 seconds old, skip spawning
            if (Date.now() - lockTime < 10000) {
                console.error('[WebSocket] Hub launch already in progress, waiting...');
                await new Promise(resolve => setTimeout(resolve, 2000));
                return;
            }
        }
        catch {
            // No lock file, proceed
        }
        // Write lock file
        try {
            fs.writeFileSync(lockPath, String(Date.now()), { mode: 0o600 });
        }
        catch {
            // If we can't write lock, proceed anyway
        }
        const __filename = fileURLToPath(import.meta.url);
        const __dirname = path.dirname(__filename);
        const hubPath = path.join(__dirname, 'hub.js');
        console.error('[WebSocket] Launching hub...');
        const child = spawn(process.execPath, [hubPath], {
            detached: true,
            stdio: 'ignore',
            env: { ...process.env, FIGMA_HUB_PORT: String(BASE_PORT) },
        });
        child.unref();
        // Wait for hub to write its port file
        await new Promise((resolve) => {
            const start = Date.now();
            const check = () => {
                const port = readPortFile();
                if (port !== null) {
                    resolve();
                    return;
                }
                if (Date.now() - start > HUB_CONNECT_TIMEOUT) {
                    resolve(); // give up waiting, tryConnect will fail
                }
                else {
                    setTimeout(check, 200);
                }
            };
            check();
        });
        // Clean up lock after hub is ready
        try {
            fs.unlinkSync(lockPath);
        }
        catch { }
    }
    tryConnectToPort(port) {
        return new Promise((resolve) => {
            try {
                const ws = new WebSocket(`ws://localhost:${port}`);
                const timeout = setTimeout(() => {
                    ws.close();
                    resolve(false);
                }, 3000);
                ws.on('open', () => {
                    clearTimeout(timeout);
                    this.ws = ws;
                    this.setupListeners();
                    // Register as MCP server
                    const token = this.readAuthToken();
                    ws.send(JSON.stringify({
                        type: 'register',
                        role: 'mcp-server',
                        sessionId: this.sessionId,
                        token,
                    }));
                    // Send client info if already available
                    if (this.mcpClientInfo) {
                        this.sendClientInfo();
                    }
                    console.error(`[WebSocket] Connected to hub on port ${port} (session: ${this.sessionId.slice(0, 8)})`);
                    resolve(true);
                });
                ws.on('error', () => {
                    clearTimeout(timeout);
                    resolve(false);
                });
            }
            catch {
                resolve(false);
            }
        });
    }
    async tryConnect() {
        // First try the port file (fastest path)
        const savedPort = readPortFile();
        if (savedPort !== null) {
            const connected = await this.tryConnectToPort(savedPort);
            if (connected)
                return true;
        }
        // Fall back to scanning all ports in parallel — first one wins
        const ports = [];
        for (let i = 0; i < PORT_RANGE; i++) {
            const port = BASE_PORT + i;
            if (port === savedPort)
                continue; // already tried
            ports.push(port);
        }
        if (ports.length === 0)
            return false;
        // Race all ports: resolve on first success, wait for all on failure
        const result = await new Promise((resolve) => {
            let settled = false;
            let pending = ports.length;
            ports.forEach((port) => {
                this.tryConnectToPort(port).then((connected) => {
                    if (connected && !settled) {
                        settled = true;
                        resolve(true);
                    }
                    else {
                        pending--;
                        if (pending <= 0 && !settled)
                            resolve(false);
                    }
                });
            });
        });
        return result;
    }
    setupListeners() {
        if (!this.ws)
            return;
        this.ws.on('message', (data) => {
            try {
                const parsed = JSON.parse(data.toString());
                // Hub status update
                if (parsed.type === 'hub-status') {
                    this.pluginConnected = parsed.pluginConnected ?? false;
                    this.pluginEditorType = parsed.editorType ?? null;
                    console.error(`[WebSocket] Plugin connected: ${this.pluginConnected}`);
                    if (parsed.hubVersion && parsed.hubVersion !== VERSION) {
                        console.error(`[WebSocket] Hub version ${parsed.hubVersion} differs from ours (${VERSION}) — continuing anyway`);
                    }
                    return;
                }
                // Plugin disconnected notification
                if (parsed.type === 'plugin-disconnected') {
                    this.pluginConnected = false;
                    this.pluginEditorType = null;
                    console.error('[WebSocket] Figma plugin disconnected');
                    // Reject all pending requests
                    for (const [id, request] of this.pendingRequests) {
                        clearTimeout(request.timeout);
                        request.reject(new Error('Figma plugin disconnected'));
                        this.pendingRequests.delete(id);
                    }
                    return;
                }
                // Plugin connected notification
                if (parsed.type === 'plugin-connected') {
                    this.pluginConnected = true;
                    this.pluginEditorType = parsed.editorType ?? null;
                    console.error('[WebSocket] Figma plugin connected');
                    return;
                }
                // Focus terminal request
                if (parsed.type === 'focus') {
                    this.focusTerminal();
                    return;
                }
                // Command response
                this.handleResponse(parsed);
            }
            catch (error) {
                console.error('[WebSocket] Failed to parse message:', error);
            }
        });
        this.ws.on('close', () => {
            console.error('[WebSocket] Disconnected from hub');
            this.ws = null;
            this.pluginConnected = false;
            // Reject pending requests
            for (const [id, request] of this.pendingRequests) {
                clearTimeout(request.timeout);
                request.reject(new Error('Disconnected from hub'));
                this.pendingRequests.delete(id);
            }
            // Try to reconnect
            this.scheduleReconnect();
        });
        this.ws.on('error', (error) => {
            console.error('[WebSocket] Error:', error.message);
        });
    }
    scheduleReconnect() {
        if (this.reconnectTimer)
            return;
        this.reconnectAttempts++;
        this.reconnectTimer = setTimeout(async () => {
            this.reconnectTimer = null;
            const connected = await this.tryConnect();
            if (connected) {
                this.reconnectAttempts = 0;
                return;
            }
            // Retry connecting several times before launching a new hub.
            // This gives a restarted hub time to start and write its token file,
            // and prevents multiple MCP servers from each killing and relaunching the hub.
            if (this.reconnectAttempts < FigmaWebSocketClient.MAX_RECONNECT_BEFORE_LAUNCH) {
                console.error(`[WebSocket] Reconnect attempt ${this.reconnectAttempts}/${FigmaWebSocketClient.MAX_RECONNECT_BEFORE_LAUNCH} — retrying...`);
                this.scheduleReconnect();
            }
            else {
                console.error('[WebSocket] Hub not found after retries — launching a new one');
                this.reconnectAttempts = 0;
                await this.launchHub();
                await this.tryConnect();
            }
        }, 2000);
    }
    handleResponse(response) {
        const pending = this.pendingRequests.get(response.id);
        if (!pending) {
            // Not for us — ignore (another MCP server's response)
            return;
        }
        clearTimeout(pending.timeout);
        this.pendingRequests.delete(response.id);
        if (response.success) {
            pending.resolve(response.result);
        }
        else {
            pending.reject(new Error(response.error || 'Unknown error'));
        }
    }
    async sendCommand(command, params = {}) {
        if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
            throw new Error('Not connected to hub. Please ensure the MCP server is running.');
        }
        if (this.pendingRequests.size >= MAX_PENDING) {
            throw new Error('Too many pending requests. Please wait for some to complete.');
        }
        const attempt = () => {
            const id = uuidv4();
            const message = { id, command, params };
            const timeoutMs = command === 'batch' ? BATCH_COMMAND_TIMEOUT : COMMAND_TIMEOUT;
            return new Promise((resolve, reject) => {
                const timeout = setTimeout(() => {
                    this.pendingRequests.delete(id);
                    reject(new Error(`Command '${command}' timed out after ${timeoutMs / 1000} seconds`));
                }, timeoutMs);
                this.pendingRequests.set(id, { resolve, reject, timeout });
                this.ws.send(JSON.stringify(message));
            });
        };
        try {
            return await attempt();
        }
        catch (error) {
            // Retry once for timeout errors on non-batch commands
            if (command !== 'batch' && error instanceof Error && error.message.includes('timed out')) {
                console.error(`[WebSocket] Retrying ${command} after timeout`);
                return await attempt();
            }
            throw error;
        }
    }
    isConnected() {
        return this.pluginConnected;
    }
    getEditorType() {
        return this.pluginEditorType;
    }
    setClientInfo(info) {
        this.mcpClientInfo = info;
        if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.sendClientInfo();
        }
    }
    sendClientInfo() {
        if (!this.ws || !this.mcpClientInfo)
            return;
        this.ws.send(JSON.stringify({
            type: 'clientInfo',
            clientInfo: this.mcpClientInfo,
        }));
        console.error(`[WebSocket] Sent client info: ${this.mcpClientInfo.name}`);
    }
    focusTerminal() {
        const ppid = process.ppid;
        const platform = process.platform;
        const termProgram = process.env.TERM_PROGRAM;
        console.error(`[WebSocket] Focus request — platform: ${platform}, terminal: ${termProgram}, ppid: ${ppid}`);
        if (platform === 'darwin') {
            this.focusMacOS(ppid, termProgram);
        }
        else if (platform === 'linux') {
            execFile('xdotool', ['search', '--pid', String(ppid), '--onlyvisible', 'windowactivate']);
        }
        else if (platform === 'win32') {
            execFile('powershell', ['-Command', `(New-Object -ComObject WScript.Shell).AppActivate(${ppid})`]);
        }
    }
    focusMacOS(ppid, termProgram) {
        // Get the TTY of the parent process to match the correct terminal tab
        execFile('ps', ['-p', String(ppid), '-o', 'tty='], (err, ttyRaw) => {
            const tty = ttyRaw?.trim();
            if (termProgram === 'Apple_Terminal' && tty) {
                const script = `
tell application "Terminal"
  activate
  repeat with w in windows
    repeat with i from 1 to count of tabs of w
      if tty of tab i of w ends with "${tty}" then
        set selected tab of w to tab i of w
        set index of w to 1
        return
      end if
    end repeat
  end repeat
end tell`;
                execFile('osascript', ['-e', script]);
            }
            else if (termProgram === 'iTerm.app') {
                const sessionId = process.env.ITERM_SESSION_ID?.split(':')[0];
                if (sessionId) {
                    const script = `
tell application "iTerm2"
  activate
  repeat with w in windows
    repeat with t in tabs of w
      repeat with s in sessions of t
        if unique ID of s contains "${sessionId}" then
          select t
          set index of w to 1
          return
        end if
      end repeat
    end repeat
  end repeat
end tell`;
                    execFile('osascript', ['-e', script]);
                }
                else {
                    execFile('osascript', ['-e', 'tell application "iTerm2" to activate']);
                }
            }
            else {
                const appName = termProgram === 'vscode' ? 'Code'
                    : termProgram === 'WarpTerminal' ? 'Warp'
                        : termProgram === 'Apple_Terminal' ? 'Terminal'
                            : null;
                if (appName) {
                    execFile('osascript', ['-e', `tell application "${appName}" to activate`]);
                }
            }
        });
    }
    close() {
        if (this.reconnectTimer) {
            clearTimeout(this.reconnectTimer);
            this.reconnectTimer = null;
        }
        if (this.ws) {
            this.ws.close();
            this.ws = null;
        }
        this.isInitialized = false;
    }
}
// Singleton instance
export const figmaWebSocket = new FigmaWebSocketClient();
